CREATE FUNCTION public.my_referral_payment_requests() RETURNS TABLE(joined_user uuid,joined_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT j.joined_user,j.joined_at FROM public.referral_vip_joins j WHERE j.referrer_id=auth.uid() AND NOT EXISTS(SELECT 1 FROM public.membership_requests r WHERE r.user_id=j.joined_user AND r.payer_id=auth.uid() AND r.status<>'rejected') AND NOT public.has_paid_bell(j.joined_user) ORDER BY j.joined_at DESC LIMIT 100 $$;
REVOKE ALL ON FUNCTION public.my_referral_payment_requests() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.my_referral_payment_requests() TO authenticated;
CREATE OR REPLACE FUNCTION public.dispatch_program_requests() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u record; n integer:=0; nid uuid; d date:=(now() AT TIME ZONE 'Asia/Kolkata')::date; BEGIN FOR u IN SELECT p.id FROM public.profiles p WHERE p.bell_activated_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.account_programs a WHERE a.user_id=p.id) AND public.has_paid_bell(p.id) AND public.can_notify(p.id) AND NOT EXISTS(SELECT 1 FROM public.program_reminders r WHERE r.user_id=p.id AND r.day=d) LIMIT 100 LOOP PERFORM 1 FROM public.profiles WHERE id=u.id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.program_reminders WHERE user_id=u.id AND day=d) THEN CONTINUE; END IF; INSERT INTO public.notifications(user_id,message) VALUES(u.id,'దయచేసి మీ ప్రొఫైల్ నింపండి') RETURNING id INTO nid; IF nid IS NOT NULL THEN INSERT INTO public.program_reminders(user_id,day,notification_id) VALUES(u.id,d,nid) ON CONFLICT DO NOTHING; n:=n+1; END IF; END LOOP; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.dispatch_program_requests() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.dispatch_program_requests() TO service_role;
CREATE FUNCTION public.notify_referral_join_payment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF public.can_notify(NEW.referrer_id) THEN INSERT INTO public.notifications(user_id,message) VALUES(NEW.referrer_id,'మీ రిఫరల్ కోడ్ తో కొత్త యూజర్ చేరారు. మీ వివరాల్లో రిఫరల్ పేమెంట్ ₹80 స్కానర్ తెరవండి.'); END IF; RETURN NEW; END $$;
CREATE TRIGGER referral_join_payment_notice AFTER INSERT ON public.referral_vip_joins FOR EACH ROW EXECUTE FUNCTION public.notify_referral_join_payment();